import { styled, View } from '@tamagui/web';

import type { ProgressBarContract } from './ProgressBar.contract';
import { ariaAndDataAttributes } from '../../helpers/ariaAndDataAttributes';
import { openStyle } from '../../helpers/openStyle';
import { prependClassName } from '../../helpers/prependClassName';
import type { WebDivProps } from '../../types/WebElementProps';

export type ProgressBarProps = WebDivProps<ProgressBarContract>;

const getWidth = (percentage: number): string => `${Math.min(Math.max(0, percentage), 100).toFixed(1)}%`;

// generated by scripts/generate-frame-values.mts from @rocket.chat/fuselage-tokens, do not edit

const progressBarFrame = {
	flexDirection: 'row',
	alignItems: 'normal',
	flexShrink: 1,
	minWidth: 'auto',
	minHeight: 'auto',
	display: 'block',
	height: 8,
	borderRadius: '$radius.large',
	overflow: 'hidden',
	width: '100%',
	backgroundColor: '$rcx-surface-neutral',
} as const;

const progressBarFill = {
	flexDirection: 'row',
	alignItems: 'normal',
	flexShrink: 1,
	minWidth: 'auto',
	minHeight: 'auto',
	display: 'block',
	height: 8,
	borderRadius: '$radius.large',
} as const;

const progressBarTones = {
	'info': {
		backgroundColor: '$rcx-status-font-on-info',
	},
	'light-info': {
		backgroundColor: '$rcx-status-background-info',
	},
	'success': {
		backgroundColor: '$rcx-status-font-on-success',
	},
	'light-success': {
		backgroundColor: '$rcx-status-background-success',
	},
	'warning': {
		backgroundColor: '$rcx-status-font-on-warning',
	},
	'light-warning': {
		backgroundColor: '$rcx-status-background-warning',
	},
	'danger': {
		backgroundColor: '$rcx-status-font-on-danger',
	},
	'light-danger': {
		backgroundColor: '$rcx-status-background-danger',
	},
} as const;

// end of generated

const ProgressBarFrame = styled(View, { render: 'div', ...progressBarFrame });

const FillFrame = styled(View, {
	render: 'div',
	...progressBarFill,
	variants: {
		tone: progressBarTones,
	},
});

/**
 * The `ProgressBar` is used to inform the user the progress of an operation.
 */
function ProgressBar(props: ProgressBarProps) {
	const { percentage, variant = 'info', error, animated, light = false, className } = props;
	const tone = error ? 'danger' : variant;

	return (
		<ProgressBarFrame
			className={prependClassName(className, 'rcx-box rcx-box--full rcx-progress-bar')}
			render={
				<div
					{...ariaAndDataAttributes(props)}
					ref={props.ref}
					id={props.id}
					title={props.title ?? (error || undefined)}
					role={props.role}
				/>
			}
		>
			<FillFrame
				tone={light ? `light-${tone}` : tone}
				className={`rcx-box rcx-box--full rcx-progress-bar__fill${animated ? ' rcx-progress-bar__fill--animated' : ''}`}
				render={<div {...openStyle({ width: getWidth(percentage) })} />}
			/>
		</ProgressBarFrame>
	);
}

export default ProgressBar;
